def rects(grid, color=8):
    R,C=len(grid),len(grid[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for i in range(R):
        for j in range(C):
            if grid[i][j]==color and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<R and 0<=nc<C and grid[nr][nc]==color and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                rs=[r for r,_ in cells]; cs=[c for _,c in cells]
                out.append((min(rs),min(cs),max(rs)-min(rs)+1,max(cs)-min(cs)+1))
    return out
