open(w+'/lib.py','w').write('''def color_runs(grid, color=8):
    """The unit cell size of a block pattern: the smallest maximal horizontal or vertical run of the color."""
    R, C, us = len(grid), len(grid[0]), []
    for r in range(R):
        j = 0
        while j < C:
            if grid[r][j] == color:
                k = j
                while k < C and grid[r][k] == color: k += 1
                us.append(k - j); j = k
            else: j += 1
    for c in range(C):
        i = 0
        while i < R:
            if grid[i][c] == color:
                k = i
                while k < R and grid[k][c] == color: k += 1
                us.append(k - i); i = k
            else: i += 1
    return min(us)

def bbox_of(grid, pred):
    """Bounding box (top, left, height, width) of all cells satisfying pred(cell)."""
    ps = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if pred(grid[r][c])]
    top = min(r for r, _ in ps); left = min(c for _, c in ps)
    return top, left, max(r for r, _ in ps) - top + 1, max(c for _, c in ps) - left + 1

def subgrid(grid, top, left, height, width):
    """The height x width subgrid whose top-left cell is (top, left)."""
    return [row[left:left + width] for row in grid[top:top + height]]

def rot_cw(grid):
    """The grid rotated a quarter turn clockwise."""
    n, m = len(grid), len(grid[0])
    return [[grid[n - 1 - j][i] for j in range(m)] for i in range(n)]

def recolor_blocks_by_key(grid, color=8):
    """Recolor each block of the color using the small multicolor key pattern rotated clockwise onto the blocks' coarse grid."""
    u = color_runs(grid, color)
    top, left, H, W = bbox_of(grid, lambda v: v == color)
    ht, hl, hh, hw = bbox_of(grid, lambda v: v not in (0, color))
    key = subgrid(grid, ht, hl, hh, hw)
    rot = rot_cw(key)
    out = [row[:] for row in grid]
    for i in range(H // u if H % u == 0 else H):
        pass
    for i in range(0, H - u + 1, u):
        for j in range(0, W - u + 1, u):
            if grid[top + i][left + j] == color:
                v = rot[i // u][j // u]
                for dr in range(u):
                    for dc in range(u):
                        out[top + i + dr][left + j + dc] = v
    return out
